body{margin:0}
.dt{display:block;width:6px;height:6px;margin:2px;border-radius:50%;background:#CFC9B9;flex:none}
.dt.w{background:#B4472F;transform:scale(1.5)}
.dt.i{background:#D9962B}
@keyframes stRise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes stFade{from{opacity:0}to{opacity:1}}
.stc{animation:stRise .6s cubic-bezier(.2,.7,.2,1) both}
.stf{animation:stFade .8s ease both}
@media (prefers-reduced-motion: reduce){.stc,.stf{animation:none}}
